head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10001.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const v_group = (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["cfi_cd"] && (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["cfi_cd"]).getValue ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["cfi_cd"]).getValue() : (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("cfi_cd") || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("cfi_cd").getValue() : ''));
        if (v_group.length === 6 && v_group.substring(0, 2) === "ES") {
            $('#slc_cbAttr1').find('option[value="' + v_group.substring(2, 3) + '"]').attr("selected", true);
            $('#slc_cbAttr2').find('option[value="' + v_group.substring(3, 4) + '"]').attr("selected", true);
            $('#slc_cbAttr3').find('option[value="' + v_group.substring(4, 5) + '"]').attr("selected", true);
            $('#slc_cbAttr4').find('option[value="' + v_group.substring(5, 6) + '"]').attr("selected", true);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendForm_onclick = function(e){
    try {
        scwin.send_form('__self.form')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10001.btn_sendForm_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.send_form = function (fm) {
    fm = (document.JLDINF10001 || { elements: [] });
    let CFIcode;
    CFIcode = "ES";
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr1').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr2').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr3').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr4').getValue();
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("cfi_cd")) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("cfi_cd")).setValue ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("cfi_cd")).setValue(CFIcode) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "cfi_cd"), void (CFIcode)));
    $c.win.closePopup();
};
